      "c": "data/cities.csv"
    },
    "code": "c.set_index(['city', 'state'])[['gestation_8_duration', 'gestation_12_duration', 'gestation_16_duration', 'gestation_20_duration']].agg(['idxmax', 'max']).T.to_string()"
  },
  {
    "id": "north-dakota-closure-8-weeks",
    "source": "Change in accessibility at 8 weeks if a clinic in North Dakota closes.",
