    "tables": {
      "c": "data/cities.csv"
    },
    "code": "c[c.state == 'North Dakota'].sort_values('population', ascending=False).set_index(['city', 'state'])[['population', 'gestation_8_duration', 'gestation_8_duration_closed']].T.to_string()"
  },
  {
    "id": "louisiana-closure-12-weeks",
