    "claim": "At 12 weeks, closing the Louisiana clinic raises round-trip times from 0 to 5 hours in Bossier City and Shreveport and from 2 to 3 hours in Longview, Texas.",
    "tables": {
      "c": "data/cities.csv"
    },
    "code": "c[c.city.isin(['Bossier City', 'Shreveport', 'Longview'])].set_index(['city', 'state'])[['gestation_12_duration', 'gestation_12_duration_closed']].T.to_string()"
  },
  {
    "id": "arkansas-closure-12-weeks",
    "source": "Change in accessibility at 12 weeks if a clinic in Arkansas closes.",
    "claim": "At 12 weeks, closing the Arkansas clinic raises round-trip times from 0 to 4 hours in Little Rock and North Little Rock and from 1 to 4 hours in Conway.",
    "tables": {
      "c": "data/cities.csv"
    },
    "code": "c[c.city.isin(['Little Rock', 'North Little Rock', 'Conway'])].set_index(['city', 'state'])[['gestation_12_duration', 'gestation_12_duration_closed']].T.to_string()"
  },
  {
    "id": "utah-closure-16-weeks",
    "source": "Change in accessibility at 16 weeks if a clinic in Utah closes.",
    "claim": "At 16 weeks, closing the Utah clinic raises round-trip times from 1 to 13 hours in Layton and Ogden, from 2 to 13 hours in Logan, and from 0 to 11 hours in Taylorsville and South Jordan.",
    "tables": {
      "c": "data/cities.csv"
    },
    "code": "c[c.city.isin(['Layton', 'Ogden', 'Logan', 'Taylorsville', 'South Jordan'])].set_index(['city', 'state'])[['gestation_16_duration', 'gestation_16_duration_closed']].T.to_string()"
  },
  {
    "id": "oklahoma-closure-16-weeks",
    "source": "Change in accessibility at 16 weeks if a clinic in Oklahoma closes.",
