    "tables": {
      "c": "data/cities.csv"
    },
    "code": "c[c.city.isin(['Norman', 'Midwest City', 'Moore', 'Edmond', 'Oklahoma City'])].set_index(['city', 'state'])[['gestation_16_duration', 'gestation_16_duration_closed']].T.to_string()"
  }
]

